descriptor.templateCss:
.pcs-card-container.reactive {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #a855f7;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.pcs-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.pcs-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.pcs-icon { font-size: 16px; }
.pcs-badge.reactive {
  font-size: 11px;
  font-weight: 700;
  color: #a855f7;
  border: 1.5px solid #a855f7;
  background: rgba(168, 85, 247, 0.1);
  padding: 2px 10px;
  border-radius: 20px;
}
.pcs-main-metric {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 4px 0;
}
.main-num.reactive {
  font-size: 34px;
  font-weight: 800;
  color: #a855f7;
  line-height: 1;
}
.main-unit {
  font-size: 16px;
  font-weight: 600;
  color: #94a3b8;
}
.reactive-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin: 6px 0;
}
.reactive-tile {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.15);
  border-radius: 10px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.tile-title { font-size: 11px; color: #94a3b8; font-weight: 600; }
.tile-val { font-size: 15px; font-weight: 700; color: #e2e8f0; }
.tile-sub { font-size: 10px; color: #a855f7; font-weight: 600; }
.pcs-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 8px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() { self.onDataUpdated(); };
self.onDataUpdated = function() {
  var data = self.ctx.data;
  var q1 = 0.8, q2 = 0.8, q3 = 0.8, qTotal = null;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var v = parseFloat(item.data[item.data.length - 1][1]);
        var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        if (!isNaN(v)) {
          if (k.indexOf('total') !== -1) qTotal = v;
          else if (k.indexOf('pcs1') !== -1 || i === 0) q1 = v;
          else if (k.indexOf('pcs2') !== -1 || i === 1) q2 = v;
          else if (k.indexOf('pcs3') !== -1 || i === 2) q3 = v;
        }
      }
    }
  }

  var finalQ = (qTotal !== null) ? qTotal : (q1 + q2 + q3);
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var elTot = container.querySelector('#q-total-val');
    if (elTot) elTot.textContent = Math.abs(finalQ).toFixed(1);

    var elBadge = container.querySelector('#q-regime-badge');
    if (elBadge) elBadge.textContent = finalQ >= 0 ? 'INDUCTIVO' : 'CAPACITIVO';

    var setQ = function(idVal, val) {
      var el = container.querySelector(idVal);
      if (el) el.textContent = val.toFixed(1) + ' kVAR';
    };
    setQ('#q-pcs1-val', q1);
    setQ('#q-pcs2-val', q2);
    setQ('#q-pcs3-val', q3);
  }
};
self.onDestroy = function() {};
